SELECT p.id,
  5, 'fielding-out-front', 'Fielding out in front',
  'Meets the ball in front of the front foot, with the glove visible and the eyes on it.',
  'A ball fielded beside or under the body cannot be seen into the glove and cannot be transferred quickly. Out in front is what makes the next two stages possible.',
  ARRAY['Glove reaches the ball out in front of the front foot', 'Ball is funnelled to the middle of the body, not caught out to the side', 'Glove stays out in front rather than tucked underneath'],
  ARRAY['Letting the ball come to the body and playing it off the chest', 'Fielding beside the foot, where the exchange has nowhere to go', 'Glove underneath, which hides the ball at exactly the wrong moment'],
  NULL,
  2, 4,
  NULL
FROM public.development_pathways p WHERE p.slug = 'infield-fundamentals';

