-- stage 2: Drop step
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  2, 'drop-step', 'Drop step',
  'Opens the hips and turns to run on a ball hit overhead, rather than backpedalling.',
  'Backpedalling is slower, less stable and caps how far back a fielder can go. It is the single most correctable outfield fault.',
  ARRAY['First step goes back and opens the hips rather than backpedalling', 'Turns and runs, then locates the ball, rather than tracking it the whole way', 'Drop steps to the weaker side look like the stronger side by the end of a session'],
  ARRAY['Backpedalling, which loses both speed and balance', 'Crossing over first, which turns the hips the wrong way', 'Watching the ball the whole way and running slowly as a result'],
  '"Open the gate" is the cue that gets the hip to rotate.',
  1, 3,
  NULL
FROM public.development_pathways p WHERE p.slug = 'outfield-development';

