SELECT p.id,
  4, 'catch-confidence', 'Catch confidence',
  'Catches a ball coming down without flinching or turning away.',
  'A player who is frightened of a fly ball will not run to one. Every later stage assumes they will.',
  ARRAY['Eyes stay on the ball all the way into the glove', 'Takes a step back without being asked to', 'Throwing hand covers the ball rather than the head turning away'],
