-- stage 7: Ground-ball approach
INSERT INTO public.development_pathway_stages
  (pathway_id, stage_number, stage_key, name, objective, why_it_matters,
   mastery_signals, common_failure_modes, coaching_emphasis,
   estimated_practices_min, estimated_practices_max, notes)
SELECT p.id,
  7, 'ground-ball-approach', 'Ground-ball approach',
  'Fields a ball on the ground in the outfield while moving through it.',
  'A single through the infield is an outfielder''s ground ball, and the difference between a single and a double is whether they charged it.',
  ARRAY['Fields the ball outside the glove-side foot while still moving', 'Arrives at the ball moving forward rather than stopped and waiting', 'Chooses the block over the charge when the situation calls for it'],
  ARRAY['Waiting for the ball and conceding a base', 'Charging everything, including when a block was the right play', 'Fielding the ball beside the body so there is no throw available'],
  NULL,
  2, 4,
  'THIN. One genuine outfield ground-ball drill exists, and it is the highest-urgency version of the play. There is nothing for the routine single, the ball to the fence, or the knee-down block the library itself references. Those are three rows of new content; they are not invented here.'
FROM public.development_pathways p WHERE p.slug = 'outfield-development';

